def R(p, s, t, status, ev='', miss='', step='', also='', kind=None, cat=None):
    RULES.append(dict(p=p, s=re.compile(s) if s else None, t=re.compile(t, re.I) if t else None, status=status,
                      ev=ev, miss=miss, step=step, also=also, kind=set(kind) if kind else None, cat=set(cat) if cat else None))


