def match(row):
    for r in RULES:
        if r['p'] is not None and r['p'] != row['part']:
            continue
        if r['s'] and not r['s'].search(row['section']):
            continue
        if r['t'] and not r['t'].search(row['text']):
            continue
        if r['kind'] and row['kind'] not in r['kind']:
            continue
        if r['cat'] and row['category'] not in r['cat']:
            continue
        return r
    return None
